tool.command:
mkdir -p run outputs && cd run &&
cp '$d_file'   model.d &&
cp '$dat_file' model.dat &&
for i in \$(seq -f "%03g" 1 $n_instances); do
    printf '%s\n' 'sim3de' '1' '$nels $nxe $nze' '$aa $bb $cc' '$thx $thy $thz' '$emn $esd' '$varfnc' '0.3' > rfem.rf &&
    rfemfield_thermal rfem model \${i} > /dev/null 2>&1;
    INST="model-\${i}";
    if [ -f "\${INST}.d" ] && [ -f "\${INST}.dat" ] && [ -f "\${INST}.mat" ]; then
        tar czf "../outputs/model-\${i}.tar.gz" "\${INST}.d" "\${INST}.dat" "\${INST}.mat";
    else
        echo "rfemfield_thermal: failed to produce files for instance \${i}" >&2;
    fi;
done
